#include <stdio.h>

#define MAXLEN 110

int getVowel(char str[], char vowel[])
{
    int i, n = 0;

    for (i = 0; str[i] != '\0'; i++) {
        char c = str[i];
        if (c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u') {
            vowel[n] = c;
            n++;
        }
    }
    vowel[n] = '\0';        /* 别忘了字符串结束符 */
    return n;
}

int main(void)
{
    char str[MAXLEN], vowel[MAXLEN];
    int len;

    scanf("%s", str);
    len = getVowel(str, vowel);
    if (len > 0) {
        printf("%d %s\n", len, vowel);
    } else {
        printf("%d\n", len);
    }
    return 0;
}

#include <stdio.h>

#define MAXLEN 110

int myStrlen(char s[])
{
    int i = 0;

    while (s[i] != '\0') {
        i++;
    }
    return i;
}

void myStrCopy(char dst[], char src[])
{
    int i = 0;

    while (src[i] != '\0') {
        dst[i] = src[i];
        i++;
    }
    dst[i] = '\0';          /* 手动补上结束符 */
}

int main(void)
{
    char src[MAXLEN], dst[MAXLEN];

    scanf("%s", src);
    myStrCopy(dst, src);
    printf("%d\n", myStrlen(dst));
    printf("%s\n", dst);
    return 0;
}

#include <stdio.h>

#define MAXLEN 110

void reversePrint(char str[])
{
    if (str[0] == '\0') {
        return;                 /* 递归出口：空串什么也不输出 */
    }
    reversePrint(str + 1);      /* 先反向输出后面部分 */
    putchar(str[0]);            /* 再输出第一个字符 */
}

int main(void)
{
    char s[MAXLEN];

    scanf("%s", s);
    reversePrint(s);
    putchar('\n');
    return 0;
}

#include <stdio.h>

#define MAXLEN 110

int main(void)
{
    char s[MAXLEN];
    int i;

    scanf("%s", s);
    for (i = 0; s[i] != '\0'; i++) {
        if (s[i] >= 'a' && s[i] <= 'z') {
            s[i] = (char)('a' + (s[i] - 'a' + 3) % 26);
        } else if (s[i] >= 'A' && s[i] <= 'Z') {
            s[i] = (char)('A' + (s[i] - 'A' + 3) % 26);
        }
    }
    printf("%s\n", s);
    return 0;
}

#include <stdio.h>

#define MAXLEN 210

int main(void)
{
    char line[MAXLEN];
    int i, start = 1;

    if (fgets(line, sizeof line, stdin) == NULL) {
        return 0;
    }
    for (i = 0; line[i] != '\0'; i++) {
        char c = line[i];

        if (c == '\n') {        /* 行尾换行符不参与处理 */
            line[i] = '\0';
            break;
        }
        if (c == ' ' || c == '\t') {
            start = 1;          /* 空白后面是新单词的首字符 */
        } else {
            if (start && c >= 'a' && c <= 'z') {
                line[i] = (char)(c - 'a' + 'A');
            }
            start = 0;
        }
    }
    printf("%s\n", line);
    return 0;
}

