#include <stdio.h>

#define MAXLEN 210

int main(void)
{
    char line[MAXLEN];
    int i, start = 0, len = 0, inWord = 0;
    int bestStart = 0, bestLen = 0;

    if (fgets(line, sizeof line, stdin) == NULL) {
        return 0;
    }
    for (i = 0; ; i++) {
        char c = line[i];

        if (c == ' ' || c == '\t' || c == '\n' || c == '\0') {
            if (inWord && len > bestLen) {   /* 结算当前单词 */
                bestLen = len;
                bestStart = start;
            }
            inWord = 0;
            len = 0;
            if (c == '\n' || c == '\0') {
                break;
            }
        } else {
            if (!inWord) {
                inWord = 1;
                start = i;
                len = 0;
            }
            len++;
        }
    }
    for (i = bestStart; i < bestStart + bestLen; i++) {
        putchar(line[i]);
    }
    putchar('\n');
    printf("%d\n", bestLen);
    return 0;
}

#include <stdio.h>

#define MAXLEN 110

long myAtoi(char s[])
{
    int i = 0, sign = 1;
    long r = 0;

    while (s[i] == ' ' || s[i] == '\t') {
        i++;                            /* 1. 跳过前导空格 */
    }
    if (s[i] == '+' || s[i] == '-') {   /* 2. 处理符号 */
        if (s[i] == '-') {
            sign = -1;
        }
        i++;
    }
    while (s[i] >= '0' && s[i] <= '9') {/* 3. 累积数字 */
        r = r * 10 + (s[i] - '0');
        i++;
    }
    return sign * r;
}

int main(void)
{
    char s[MAXLEN];

    if (fgets(s, sizeof s, stdin) == NULL) {
        return 0;
    }
    printf("%ld\n", myAtoi(s));
    return 0;
}

#include <stdio.h>

#define MAXS 210
#define MAXT 60

int main(void)
{
    char s[MAXS], t[MAXT];
    int len1 = 0, len2 = 0, i, j, cnt = 0;

    scanf("%s", s);
    scanf("%s", t);
    while (s[len1] != '\0') {
        len1++;
    }
    while (t[len2] != '\0') {
        len2++;
    }
    for (i = 0; i + len2 <= len1; i++) {
        for (j = 0; j < len2; j++) {
            if (s[i + j] != t[j]) {
                break;
            }
        }
        if (j == len2) {        /* 内层没被 break 打断，说明匹配成功 */
            cnt++;
        }
    }
    printf("%d\n", cnt);
    return 0;
}

#include <stdio.h>

#define MAXLEN 110

int isPrime(int n)
{
    int i;

    if (n < 2) {
        return 0;
    }
    for (i = 2; i * i <= n; i++) {
        if (n % i == 0) {
            return 0;
        }
    }
    return 1;
}

int getResult(char word[])
{
    int cnt[26] = {0};
    int i, max = 0, min = -1, diff;

    for (i = 0; word[i] != '\0'; i++) {
        cnt[word[i] - 'a']++;
    }
    for (i = 0; i < 26; i++) {
        if (cnt[i] > 0) {       /* 只统计出现过的字母 */
            if (cnt[i] > max) {
                max = cnt[i];
            }
            if (min == -1 || cnt[i] < min) {
                min = cnt[i];
            }
        }
    }
    if (min == -1) {
        return -1;
    }
    diff = max - min;
    return isPrime(diff) ? diff : -1;
}

int main(void)
{
    char word[MAXLEN];

    scanf("%s", word);
    printf("%d\n", getResult(word));
    return 0;
}

