int main(void)
{
    int weight[17] = {7, 9, 10, 5, 8, 4, 2, 1, 6, 3, 7, 9, 10, 5, 8, 4, 2};
    char code[11] = {'1', '0', 'X', '9', '8', '7', '6', '5', '4', '3', '2'};
