        if (id[17] == code[rest]) {
            printf("right\n");
        } else {
            printf("wrong\n");
        }
    }
    return 0;
}

#include <stdio.h>

#define MAXS 210
#define MAXP 30
#define MAXR 4200

int main(void)
{
    char s[MAXS], a[MAXP], b[MAXP], res[MAXR];
    int len1 = 0, la = 0, lb = 0;
    int i = 0, k = 0, j;

    scanf("%s", s);
    scanf("%s", a);
    scanf("%s", b);
    while (s[len1] != '\0') {
        len1++;
    }
    while (a[la] != '\0') {
        la++;
    }
    while (b[lb] != '\0') {
        lb++;
    }
    while (i < len1) {
        j = 0;
        if (i + la <= len1) {
            while (j < la && s[i + j] == a[j]) {
                j++;
            }
        }
        if (j == la) {              /* 匹配成功：整段替换 */
            for (j = 0; j < lb; j++) {
                res[k] = b[j];
                k++;
            }
            i += la;
        } else {                    /* 匹配失败：原样复制一个字符 */
            res[k] = s[i];
            k++;
            i++;
        }
    }
    res[k] = '\0';
    printf("%s\n", res);
    return 0;
}

#include <stdio.h>

#define MAXLEN 210
#define MAXR 900

int main(void)
{
    char s[MAXLEN], res[MAXR];
    int len = 0, i = 0, k = 0;

    scanf("%s", s);
    while (s[len] != '\0') {
        len++;
    }
    while (i < len) {
        int j = i;

        while (j < len && s[j] == s[i]) {
            j++;                        /* 数出这一段连续相同的字符个数 */
        }
        k += snprintf(res + k, sizeof res - k, "%c%d", s[i], j - i);
        i = j;
    }
    res[k] = '\0';
    if (k < len) {
        printf("%s\n", res);
    } else {
        printf("%s\n", s);
    }
    return 0;
}

#include <stdio.h>

#define MAXLEN 110

int main(void)
{
    char s[MAXLEN], res[MAXLEN];
    int n = 0, i;
    long long k;

    scanf("%s", s);
    scanf("%lld", &k);
    while (s[n] != '\0') {
        n++;
    }
    k %= n;                             /* 大 k 先取模 */
    for (i = 0; i < n; i++) {
        res[i] = s[(i + (int)k) % n];
    }
    res[n] = '\0';
    printf("%s\n", res);
    return 0;
}

#include <stdio.h>
#include <string.h>

#define MAXN 60
#define MAXLEN 35

int cmp(char a[], char b[])
{
    int la = (int)strlen(a);
    int lb = (int)strlen(b);

    if (la != lb) {
        return la - lb;         /* 先比长度 */
    }
    return strcmp(a, b);        /* 长度相同比字典序 */
}

int main(void)
{
    char w[MAXN][MAXLEN], t[MAXLEN];
    int n, i, j;

    scanf("%d", &n);
    for (i = 0; i < n; i++) {
        scanf("%34s", w[i]);
    }
    for (i = 0; i < n - 1; i++) {           /* 冒泡排序 */
        for (j = 0; j < n - 1 - i; j++) {
            if (cmp(w[j], w[j + 1]) > 0) {
                strcpy(t, w[j]);
                strcpy(w[j], w[j + 1]);
                strcpy(w[j + 1], t);
            }
        }
    }
    for (i = 0; i < n; i++) {
        printf("%s\n", w[i]);
    }
    return 0;
}
